### Worked example — a Material-3-flavoured Button

```rust
use std::rc::Rc;

use teksilo_core::build_context::BuildContext;
use teksilo_core::styles::{ButtonStyle, ButtonStyleConfig};
use teksilo_core::widget_id::WidgetId;
use teksilo_tokens::{Color, CornerRadius, SurfaceRole};
use teksilo_widgets::primitives::{Padding, RectWidget, ZStack};

struct MaterialFilledButton;

impl ButtonStyle for MaterialFilledButton {
    fn make_body(&self, cfg: &ButtonStyleConfig, ctx: &mut BuildContext) -> WidgetId {
        // Material 3 filled buttons are tall (40 dp), pill-shaped, with
        // a small elevation that lifts on hover. State-driven `Accent` /
        // `AccentHover` / `AccentPressed` cover the surface; disabled
        // collapses to a flat translucent grey.
        let bg = cfg.is_pressed
            .zip3(&cfg.is_hovered, &cfg.is_disabled)
            .map(|(pressed, hovered, disabled)| {
                if *disabled { SurfaceRole::AccentDisabled }
                else if *pressed { SurfaceRole::AccentPressed }
                else if *hovered { SurfaceRole::AccentHover }
                else { SurfaceRole::Accent }
            });

        let rect = ctx.add(
            RectWidget::new()
                .background(bg)
                .corner_radius(CornerRadius::uniform(20.0)),
        );

        let padded_label = ctx.add(
            Padding::symmetric(10.0, 24.0)     // M3 spec: 10×24
                .child_id(cfg.label),
        );

        ctx.add(ZStack::new().add_child(rect).add_child(padded_label))
    }
}
```

Install per-call: `Button::new(lit!("Save")).style(MaterialFilledButton)`.
Install theme-wide:

```rust
let mut theme = intui::light();
theme.style_slots.button = Some(Rc::new(MaterialFilledButton));
```

The widget honours this precedence at every `build()`:

```
per-call .style(...)  >  theme.style_slots.button  >  RecipeButtonStyle::default()
```

Tested end-to-end in
[`teksilo-widgets/src/button.rs`](../crates/teksilo-widgets/src/button.rs)
under `theme_slot_supplies_button_style_when_no_override` /
`per_call_style_override_wins_over_theme_slot`.

## At a glance

```rust
use teksilo::data::ListModel;
use teksilo::prelude::*;
use teksilo::widgets::{
    TabBarOrientation, TabDisplayMode, TabHandle, TabId, TabInfo, TabSizing, TabWidget,
    TextWidget, VStack,
};

#[derive(Debug)]
struct DocState {
    title: String,
    edits: Signal<usize>,
}

let selected: Signal<Option<TabId>> = Signal::new(None);
let model: ListModel<TabHandle> = ListModel::from_vec(vec![
    TabHandle::dynamic(
        TabId::fresh(),
        "doc",
        TabInfo::new()
            .title(lit!("Doc 1"))
            .closable(true),
        DocState { title: "Doc 1".into(), edits: Signal::new(0) },
    ),
]);

let tw = TabWidget::new(selected.clone())
    .static_tab(
        TabInfo::new()
            .title(lit!("Welcome"))
            .pinned(true),
        TextWidget::new(lit!("Welcome page")),
    )
    .dynamic_tab::<DocState>("doc", |_handle, state| {
        Box::new(VStack::new()
            .child(TextWidget::new(lit!(state.title.clone())))
            .child(TextWidget::new(lit!("…")))) as Box<dyn Widget>
    })
    .dynamic_model(model.clone())
    .reorderable(true)
    .tab_sizing(TabSizing::Shared);
```

Stand-alone `TabBar<T>` looks the same minus the content-side machinery.
`TabBar` is generic over any item type `T`; supply a `TabDelegate<T>` that
extracts presentation from your items and an `id_of` closure that produces
the stable `TabId` for each item:

```rust
use teksilo::widgets::{TabBar, TabDelegate};

// Example with a custom item type.
struct DocItem { id: TabId, title: String, closable: bool, pinned: bool }

let bar = TabBar::horizontal(
    model,   // ListModel<DocItem>
    TabDelegate::new(|_, item: &DocItem| lit!(item.title.clone()))
        .closable(|_, item| item.closable)
        .pinned(|_, item| item.pinned),
    selected,
    |_, item: &DocItem| item.id,
)
.tab_sizing(TabSizing::Shared)
.reorderable(true);
```

