    use super::*;

    fn spans(hl: &dyn SyntaxHighlighter, text: &str) -> Vec<teksilo::text_document::HighlightSpan> {
        let mut ctx = HighlightContext::new(0, -1, None);
        hl.highlight_block(text, &mut ctx);
        let (spans, _, _) = ctx.into_parts();
