// ---------------------------------------------------------------------------
// Decorative connectors
// ---------------------------------------------------------------------------

fn add_section_connector(
    scene: &mut Scene,
    from_section: (usize, usize),
    to_section: (usize, usize),
) {
    let from_rect = section_rect(from_section.0, from_section.1);
    let to_rect = section_rect(to_section.0, to_section.1);
    let from = Point::new(
        from_rect.x + from_rect.width,
        from_rect.y + from_rect.height * 0.5,
    );
    let to = Point::new(to_rect.x, to_rect.y + to_rect.height * 0.5);
    let mid_x = (from.x + to.x) * 0.5;
    let mut path = Path::new();
    path.move_to(from)
        .line_to(Point::new(mid_x, from.y))
        .line_to(Point::new(mid_x, to.y))
        .line_to(to);
    let stroke_w = 3.0;
    scene.add_item(
        PathItem::new(path).stroke_cosmetic(connector_color(), stroke_w),
        Point::ZERO,
    );
}

// ---------------------------------------------------------------------------
// Whole-scene assembly
// ---------------------------------------------------------------------------

fn build_showcase_view() -> (SceneView, ItemId) {
    let mut scene = Scene::new();

    add_scene_header(&mut scene);

    build_lightweight_items_section(&mut scene);
    build_groupitem_section(&mut scene);
    build_zorder_section(&mut scene);
    let scroll_area_id = build_heavyweight_section(&mut scene);
    let swatch_id = build_drag_section(&mut scene);
    build_a11y_groups_section(&mut scene, scroll_area_id);
    build_nested_scene_section(&mut scene);
    build_animation_section(&mut scene);

    add_section_connector(&mut scene, (0, 0), (1, 0));
    add_section_connector(&mut scene, (1, 0), (2, 0));
    add_section_connector(&mut scene, (2, 0), (3, 0));
    add_section_connector(&mut scene, (0, 1), (1, 1));
    add_section_connector(&mut scene, (1, 1), (2, 1));
    add_section_connector(&mut scene, (2, 1), (3, 1));

    let (w, h) = scene_extent();
    // Movement policy demo: clamp the visible viewport to the scene
    // extent so the user can't pan into empty space, and keep zoom in a
    // readable band. Both are reactive Scene-level signals.
    scene.set_pan_bounds(Some(Rect::new(0.0, 0.0, w, h)));
    scene.set_zoom_range(Some(0.5_f32..=3.0_f32));
    let view = SceneView::new(scene)
        .selection_mode(SceneSelectionMode::Multi)
        .default_size(w, h)
        // Start slightly zoomed in so the content overflows the viewport and
        // the scroll bars are active and draggable on launch. Zooming back out
        // to fit hides them again (the `AsNeeded` policy in `build_root`).
        .initial_zoom(1.4)
        // R5 background closure: paints a zoom-aware 50-unit grid in
        // scene coords. The closure receives the visible scene region,
        // so off-screen lines are skipped — at zoom 0.1× over a
        // 50,000-unit scene we still emit only the lines on screen.
        // The grid uses a HAIRLINE stroke (StrokeStyle::hairline): a
        // transform-invariant 1px line that stays crisp at every zoom
        // instead of thinning out and vanishing.
        .background(|canvas, _ctx, region| {
            let step = 50.0_f32;
            let color = faint_grid();
            let x0 = (region.x / step).floor() * step;
            let y0 = (region.y / step).floor() * step;
            let x_end = region.x + region.width;
            let y_end = region.y + region.height;
            let mut x = x0;
            while x <= x_end {
                canvas.draw_line(
                    teksilo::canvas::Point::new(x, region.y),
                    teksilo::canvas::Point::new(x, y_end),
                    color,
                    StrokeStyle::hairline(1.0),
                );
                x += step;
            }
            let mut y = y0;
            while y <= y_end {
                canvas.draw_line(
                    teksilo::canvas::Point::new(region.x, y),
                    teksilo::canvas::Point::new(x_end, y),
                    color,
                    StrokeStyle::hairline(1.0),
                );
                y += step;
            }
        });
    (view, swatch_id)
}

// ---------------------------------------------------------------------------
// Reactive header
// ---------------------------------------------------------------------------

fn build_status_row(view: &SceneView) -> impl Widget + 'static {
    let pan_x = view.pan_x_signal();
    let pan_y = view.pan_y_signal();
    let zoom = view.zoom_signal();
    let selection = view.selection().selection_signal();
    let drag = view.drag_mode_signal();

    let pan_text = pan_x
        .zip(&pan_y)
        .map(|(x, y)| format!("Pan: ({:>6.1}, {:>6.1})", x, y));
    let zoom_text = zoom.map(|z| format!("Zoom: ×{:.2}", z));
    let sel_text = selection.map(|s| format!("Selected items: {}", s.len()));
    let drag_text = drag.map(|m| {
        let label = match m {
            DragMode::RubberBand => "Marquee",
            DragMode::ScrollHandDrag => "Pan",
            DragMode::NoDrag => "None",
        };
        format!("Drag: {label}")
    });

    HStack::new()
        .spacing(28.0)
        .child(
            TextWidget::new(lit!(""))
                .text(pan_text)
                .style(TextStyleRole::Body),
        )
        .child(
            TextWidget::new(lit!(""))
                .text(zoom_text)
                .style(TextStyleRole::Body),
        )
        .child(
            TextWidget::new(lit!(""))
                .text(sel_text)
                .style(TextStyleRole::Body),
        )
        .child(
            TextWidget::new(lit!(""))
                .text(drag_text)
                .style(TextStyleRole::Body),
        )
}

fn build_toolbar(drag_mode: Signal<DragMode>, scene: SceneModel, swatch_id: ItemId) -> impl Widget {
    // Cycles the live-recolour swatch (§5) through a small palette. Kept
    // outside the closure body only so the palette array itself is `Copy`
    // and doesn't need cloning per activation.
    let swatch_palette = [pastel_red(), pastel_blue(), pastel_green(), pastel_yellow()];
    let swatch_phase = Signal::new(0_usize);
    Toolbar::new().child(
        HStack::new()
            .spacing(12.0)
            .child(
                Button::new(lit!("Drag mode: Marquee ⇄ Pan")).on_activate_fn(move |_ctx| {
                    // Flip between marquee box-select and scroll-hand pan.
                    let next = match drag_mode.get() {
                        DragMode::ScrollHandDrag => DragMode::RubberBand,
                        _ => DragMode::ScrollHandDrag,
                    };
                    drag_mode.set(next);
                }),
            )
            .child(
                Button::new(lit!("Recolour swatch")).on_activate_fn(move |_ctx| {
                    // Live colour mutation: `SceneModel::set_item_fill` repaints
                    // the §5 swatch in place — no scene rebuild, no relayout.
                    let phase = (swatch_phase.get() + 1) % swatch_palette.len();
                    swatch_phase.set(phase);
                    scene.set_item_fill(swatch_id, swatch_palette[phase]);
                }),
            )
            .child(Spacer::new())
            .child(teksilo::widgets::ThemeSwitcher::new()),
    )
}

fn build_root() -> impl Widget + 'static {
    let (view, swatch_id) = build_showcase_view();
    let drag_mode = view.drag_mode_signal();
    let scene_model = view.model();
    let status = build_status_row(&view);

    // Minimap: a bottom-trailing thumbnail of the whole scene with a live
    // viewport rectangle. Read its inputs from the view *before* moving `view`
    // into the ZStack. `item_thumbnails()` snapshots both tiers (cards + the
    // lightweight grid/connectors); the viewport rect is reactive on its own,
    // tracking pan / zoom with no extra plumbing. (A live "items as they move"
    // minimap would re-snapshot on mutation; this showcase scene is static.)
    let content = view.scene_content_bounds().unwrap_or_else(|| {
        let (w, h) = scene_extent();
        Rect::new(0.0, 0.0, w, h)
    });
    let item_thumbs = view.scene().item_thumbnails();
    let visible_scene = view.viewport_in_scene_signal();
    let minimap_zoom = view.zoom_signal();

    // Wrap the view in a SceneScrollView so the viewport gains overlay scroll
    // bars. They track pan/zoom and let the user scroll by dragging; native
    // wheel / hand-drag panning keeps working. `view` is consumed here — every
    // signal the minimap / status row needed was captured above first.
    let scrollable = view
        .with_scroll_bars()
        .scroll_bar_mode(ScrollBarMode::Overlay)
        .vertical_policy(ScrollBarPolicy::AsNeeded)
        .horizontal_policy(ScrollBarPolicy::AsNeeded);

    // `on_click` asks the app to **centre the view on this scene point**, and
    // the minimap's keyboard / AT routes compute their destination and their
    // announcement on the assumption that it does. `SceneView` has no
    // one-call "centre here", so drive the camera through the scroll view's
    // own door: its `scroll_pos_*` signals are the pan the scroll bars write,
    // expressed in screen pixels from the leading edge of the scrollable
    // extent, and `max_scroll_*` is exactly how far that extent allows. Going
    // through them (rather than writing `pan_x_signal` directly) keeps the
    // move inside the scene's `set_pan_bounds` clamp and leaves the bars in
    // step with the thumbnail for free.
    //
    // The delta is computed in scene units and scaled by zoom: scroll grows as
    // the content moves toward the viewport's leading edge, which is the same
    // direction the target is from the current centre.
    let scroll_x = scrollable.scroll_pos_x_signal().clone();
    let scroll_y = scrollable.scroll_pos_y_signal().clone();
    let max_scroll_x = scrollable.max_scroll_x_signal().clone();
    let max_scroll_y = scrollable.max_scroll_y_signal().clone();
    let visible_for_click = visible_scene.clone();
    let recentre_on = move |scene_pt: Point| {
        let zoom = minimap_zoom.get();
        if !zoom.is_finite() || zoom <= 0.0 {
            return;
        }
        let centre = visible_for_click.get().center();
        // `max.max(0.0)` rather than a bare `max`: `f32::clamp` panics on a
        // NaN bound, and the scroll metrics are the scroll view's numbers,
        // not ours to assume finite.
        let to = |pos: f32, delta: f32, max: f32| (pos + delta * zoom).clamp(0.0, max.max(0.0));
        scroll_x.set(to(
            scroll_x.get(),
            scene_pt.x - centre.x,
            max_scroll_x.get(),
        ));
        scroll_y.set(to(
            scroll_y.get(),
            scene_pt.y - centre.y,
            max_scroll_y.get(),
        ));
    };

    let minimap = SceneMinimap::new(content, visible_scene)
        .items(item_thumbs)
        .size(240.0, 160.0)
        .background(Color::new(0.10, 0.11, 0.15, 0.82))
        .border(Some((Color::new(1.0, 1.0, 1.0, 0.35), 1.0)))
        .content_outline(Some((Color::new(1.0, 1.0, 1.0, 0.18), 1.0)))
        .viewport_color(Color::new(0.40, 0.66, 1.0, 0.95))
        .on_click(move |scene_pt, _ctx| recentre_on(scene_pt));

    VStack::new()
        .spacing(8.0)
        .child(build_toolbar(drag_mode, scene_model, swatch_id))
        .child(TextWidget::new(lit!("teksilo-scene showcase")).style(TextStyleRole::BodyBold))
        .child(status)
        .child(
            // Overlay the minimap on the viewport's bottom-trailing corner.
            Expand::new().child(
                ZStack::new()
                    .alignment(Alignment::BOTTOM_TRAILING)
                    .child(Expand::new().child(scrollable))
                    .child(Padding::new(12.0, 12.0, 12.0, 12.0).child(minimap)),
            ),
        )
}

fn main() {
    TeksiloAppBuilder::new()
        .install_automation_bridge_in_debug()
        .install_inspector_in_debug()
        .theme(teksilo::presets::intui::light())
        .initial_window(
            WindowConfig::new()
                .title("Teksilo — teksilo-scene showcase")
                .size(1500, 950)
                .root(|tree, _state| tree.add(build_root())),
        )
        .run();
}

#[cfg(test)]
mod tests {
    use super::*;
    use teksilo::core::WidgetTree;
    use teksilo::core::widget_id::WidgetId;

    /// Depth-first search for the one widget of a given concrete Rust type.
    ///
    /// `widget_type_name` returns the fully-qualified path, so the needle is
    /// matched as a suffix — that survives the module moving without matching
    /// a different crate's same-named widget.
    fn find_by_type(tree: &WidgetTree, from: WidgetId, needle: &str) -> Option<WidgetId> {
        if tree
            .widget_type_name(from)
            .is_some_and(|n| n.ends_with(needle))
        {
            return Some(from);
        }
        tree.children(from)
            .into_iter()
            .find_map(|child| find_by_type(tree, child, needle))
    }

    /// The showcase's minimap is the **interactive** variant, and the wiring
    /// behind its `on_click` really moves the camera.
    ///
    /// Worth an end-to-end test rather than a reading of the source, because
    /// every non-pointer route on `SceneMinimap` is gated on an `on_click`
    /// being installed: focus, the arrow / `Home` / `Enter` / `Space` keys and
    /// all five advertised AccessKit actions. A showcase that omitted the
    /// callback would ship the read-only variant, and a reviewer who came here
    /// to try the arrows would find the minimap takes no focus at all and
    /// conclude the feature does not work. That is exactly what it did.
    ///
    /// Asserting the Tab stop alone would pass on a minimap whose callback did
    /// nothing, so this taps it and watches the view move. The minimap's own
    /// accessible value is the probe: it reads the live viewport out of the
    /// same signal the overlay is drawn from, so it changes if and only if the
    /// camera did.
    #[test]
    fn the_showcase_minimap_is_a_control_that_recentres_the_view() {
        use teksilo::core::accessibility::widget_id_to_node_id;

        let mut tree = WidgetTree::new().with_theme(teksilo::presets::intui::light());
        let root = tree.add(build_root());
        tree.layout(SizeProposal::exact(1500.0, 950.0));
        let _ = tree.render();

        let minimap = find_by_type(&tree, root, "SceneMinimap")
            .expect("build_root places a SceneMinimap over the scene viewport");
        assert!(
            tree.tab_stops_within(root).contains(&minimap),
            "the showcase minimap must be keyboard-reachable — it is only \
             focusable when an `on_click` is installed, so this failing means \
             the demo ships the read-out variant"
        );

        let position = |tree: &mut WidgetTree| -> String {
            let update = tree.sync_accessibility();
            update
                .nodes
                .iter()
                .find(|(id, _)| *id == widget_id_to_node_id(minimap))
                .and_then(|(_, node)| node.value().map(str::to_owned))
                .expect("the minimap announces where the viewport is")
        };
        let before = position(&mut tree);

        // The view starts at the scene's top-leading corner (pan 0, zoom 1.4),
        // so a tap well down and across the thumbnail has somewhere to go.
        let b = tree.bounds(minimap);
        tree.tap_with(
            teksilo::tokens::PointerKind::Mouse,
            Point::new(b.x + b.width * 0.8, b.y + b.height * 0.8),
        );
        tree.layout(SizeProposal::exact(1500.0, 950.0));
        let _ = tree.render();

        assert_ne!(
            before,
            position(&mut tree),
            "tapping the minimap must recentre the view — `on_click` is wired \
             to the scroll view's scroll position, and the minimap reads the \
             viewport back out of the signal the camera writes"
        );
    }

    /// The keyboard route the module doc advertises works in this tree, not
    /// only in the widget's own unit tests.
    ///
    /// This is the exact thing a reviewer does — run the demo, Tab to the
    /// minimap, press an arrow — and the thing that silently did nothing
    /// before, because the arrows are installed alongside the pointer handler
    /// and neither existed without `on_click`.
    #[test]
    fn the_showcase_minimap_moves_the_view_from_the_keyboard() {
        use teksilo::core::accessibility::widget_id_to_node_id;
        use teksilo::core::event::{Key, Modifiers, WidgetEvent};

        let mut tree = WidgetTree::new().with_theme(teksilo::presets::intui::light());
        let root = tree.add(build_root());
        tree.layout(SizeProposal::exact(1500.0, 950.0));
        let _ = tree.render();

        let minimap = find_by_type(&tree, root, "SceneMinimap").expect("a minimap");
        let position = |tree: &mut WidgetTree| -> String {
            let update = tree.sync_accessibility();
            update
                .nodes
                .iter()
                .find(|(id, _)| *id == widget_id_to_node_id(minimap))
                .and_then(|(_, node)| node.value().map(str::to_owned))
                .expect("the minimap announces where the viewport is")
        };
        let before = position(&mut tree);

        // The view starts at the scene's top-leading corner, so both of these
        // have room to move; `Shift` is the page step, a whole viewport.
        tree.focus(minimap);
        for key in [Key::ArrowRight, Key::ArrowDown] {
            tree.dispatch_event(WidgetEvent::KeyDown {
                key,
                modifiers: Modifiers::SHIFT,
                text: None,
            });
        }
        tree.layout(SizeProposal::exact(1500.0, 950.0));
        let _ = tree.render();

        assert_ne!(
            before,
            position(&mut tree),
            "Shift+Arrow on the focused minimap must page the view — the demo \
             has to exercise the keyboard route, not just compile it"
        );
    }

    #[test]
    fn showcase_root_lays_out_without_panicking() {
        let mut tree = WidgetTree::new().with_theme(teksilo::presets::intui::light());
        let _root = tree.add(build_root());
        tree.layout(SizeProposal::exact(1500.0, 950.0));
    }

    #[test]
    fn outer_scene_has_two_heavyweight_children() {
        // 1 ScrollArea (§4, wraps 3 cards as ScrollArea descendants)
        // + 1 inner SceneView (§7) = 2 direct heavyweight children.
        let mut tree = WidgetTree::new().with_theme(teksilo::presets::intui::light());
        let (view, _swatch_id) = build_showcase_view();
        let view_id = tree.add(view);
        tree.layout(SizeProposal::exact(1500.0, 950.0));
        let kids = tree.children(view_id);
        assert_eq!(kids.len(), 2);
    }

    #[test]
    fn scene_extent_fits_the_default_window() {
        // Showcase claim: at zoom 1.0 the entire scene fits in
        // ~1500×950 minus header. Verify the math.
        let (w, h) = scene_extent();
        assert!(w <= 1500.0, "scene width {} must fit in 1500 window", w);
        assert!(h <= 870.0, "scene height {} must fit below ~80px header", h);
    }

    #[test]
    fn showcase_scroll_bars_appear_when_zoomed_content_overflows() {
        // The showcase starts at initial_zoom(1.4), so the 1490×780 scene
        // overflows a typical scene-area viewport — both AsNeeded bars should
        // be placed with real (non-zero) bounds at the viewport edges.
        let mut tree = WidgetTree::new().with_theme(teksilo::presets::intui::light());
        let (view, _swatch_id) = build_showcase_view();
        let scrollable = view
            .with_scroll_bars()
            .scroll_bar_mode(ScrollBarMode::Overlay)
            .vertical_policy(ScrollBarPolicy::AsNeeded)
            .horizontal_policy(ScrollBarPolicy::AsNeeded);
        let id = tree.add(scrollable);
        // A realistic scene-area size (window minus toolbar/title/status chrome).
        tree.layout(SizeProposal::exact(1480.0, 800.0));

        let kids = tree.children(id);
        assert_eq!(kids.len(), 3, "scene_view + v_bar + h_bar");
        let v = tree.bounds(kids[1]);
        let h = tree.bounds(kids[2]);
        assert!(
            v.width > 0.0 && v.height > 0.0,
            "vertical scroll bar should be visible, got {:?}",
            v
        );
        assert!(
            h.width > 0.0 && h.height > 0.0,
            "horizontal scroll bar should be visible, got {:?}",
            h
        );
        // Vertical bar hugs the trailing (right) edge; horizontal bar the bottom.
        assert!(
            (v.x + v.width - 1480.0).abs() < 0.5,
            "v bar at right edge, got x={} w={}",
            v.x,
            v.width
        );
        assert!(
            (h.y + h.height - 800.0).abs() < 0.5,
            "h bar at bottom edge, got y={} h={}",
            h.y,
            h.height
        );
    }
}

