                            }
                        }
                    }
                }
            }

            VStack {
                spacing: 6.0
                TextWidget::new(lit!("SmoothSize")) {
                    style: TextStyleRole::SmallBold
                    color: TextRole::Accent
                }
                SmoothSize {
                    Panel {
                        background: SurfaceRole::AccentSubtle
                        padding: 12.0
                        TextWidget::new(tr!(anim_smooth_body())) {
                            style: TextStyleRole::Body
                        }
                    }
                }
            }

            VStack {
                spacing: 6.0
                TextWidget::new(lit!("Slide")) {
