    );
    let table_view = section(
        ctx,
        lit!("TableView"),
        sized(540.0, 200.0, table_view_widget()),
    );
    let tree_table = section(
        ctx,
        lit!("TreeTableView"),
        sized(540.0, 200.0, tree_table_widget()),
    );
    let grid_view = section(
        ctx,
        lit!("GridView"),
        sized(540.0, 230.0, grid_view_widget()),
