//! Settings tab — ShortcutSettings + live PrivacySettings (telemetry consent UI).

use teksilo::prelude::*;
use teksilo::widgets::{
    Divider, Expand, LanguageSwitcher, Panel, PrivacySettings, ShortcutSettings, TextScaleControl,
    TextWidget, ThemeSwitcher, VStack,
