            ))
            .child(labelled(
                "Square",
                Toggle::new(tog_square)
                    .variant(ToggleVariant::Square)
                    .label(lit!("Square")),
            ))
            .child(labelled(
                "Inset",
                Toggle::new(tog_inset)
                    .variant(ToggleVariant::Inset)
                    .label(lit!("Inset")),
            )),
