                        }
                    }
                }
            }

            VStack {
                spacing: 6.0
                TextWidget::new(lit!("SpinBox")) {
                    style: TextStyleRole::SmallBold
                    color: TextRole::Accent
                }
                SpinBox::new(spin_sig, 0.0_f64, 100.0_f64) {
                    single_step: 1.0
                    decimals: 2
                }
            }

            VStack {
                spacing: 6.0
                TextWidget::new(lit!("SearchField")) {
                    style: TextStyleRole::SmallBold
                    color: TextRole::Accent
                }
                #{ search_id }
            }

            VStack {
                spacing: 6.0
                TextWidget::new(lit!("PasswordField")) {
                    style: TextStyleRole::SmallBold
