    let field = ctx.signal(String::new());
    let text_id = section(
        ctx,
        tr!(touch_section_text()),
        VStack::new()
            .spacing(6.0)
            .child(note(tr!(touch_text_note())))
            .child(TextInput::new(field).placeholder(tr!(touch_text_placeholder()))),
    );

    ctx.add(
        VStack::new()
            .spacing(20.0)
            .child(header)
            .child(Divider::new())
            .child(ladder_id)
            .child(profiles_id)
            .child(pan_id)
            .child(manipulator_id)
