                    style: TextStyleRole::SmallBold
                    color: TextRole::Accent
                }
                #{ profiles_id }
                TextWidget::new(tr!(touch_profiles_note())) {
                    style: TextStyleRole::Small
                    color: TextRole::Secondary
                }
            }

            VStack {
                spacing: 6.0
