            .child(
                ImageWidget::new(star_icon)
                    .size(48.0, 48.0)
                    .mask(ImageMaskShape::Circle)
                    .alt(tr!(vis_image_alt_2()).resolve_now()),
            )
            .child(
                ImageWidget::new(star_icon)
                    .size(48.0, 48.0)
                    .mask(ImageMaskShape::RoundedSquare(0.25))
                    .alt(tr!(vis_image_alt_3()).resolve_now()),
            ),
    );
    let twist_expanded = ctx.signal(true);
    let twist_classic = twist_expanded.clone();
    let twist = section(
        ctx,
        lit!("TwistArrow"),
        demo_row(8.0)
            .child(TwistArrow::new(16.0, true, true).on_click(move |_ctx| {
                twist_classic.set(!twist_classic.get());
            }))
            .child(TwistArrow::new(16.0, true, false).on_click(|_ctx| {}))
            .child(TwistArrow::new(16.0, false, false).on_click(|_ctx| {})),
    );
    let panel_demo = section(
        ctx,
        tr!(vis_panel_standalone()),
        Panel::new()
            .background(SurfaceRole::Raised)
            .border_color(BorderRole::Default)
            .border_width(1.0)
            .corner_radius(8.0)
            .padding(12.0)
            .child(TextWidget::new(tr!(vis_panel_body())).style(TextStyleRole::Small)),
    );

    ctx.add(
        VStack::new()
            .spacing(20.0)
            .child(header)
            .child(Divider::new())
            .child(rect)
            .child(text)
            .child(icon)
            .child(image)
            .child(twist)
            .child(panel_demo),
    )
}

